content.query:
// Daily network activity in the workbook-selected period
let CurrentDailyActivity =
    DeviceNetworkEvents
    | where Timestamp {TimeRange}
    | summarize Connections = count() by Day = startofday(Timestamp);

// Start of the selected period
let SelectedStart =
    toscalar(
        CurrentDailyActivity
        | summarize min(Day)
    );

// Daily network activity during the 30 days before the selected period
let BaselineDailyActivity =
    DeviceNetworkEvents
    | where Timestamp >= SelectedStart - 30d
    | where Timestamp < SelectedStart
    | summarize Connections = count() by Day = startofday(Timestamp);

// Current selected-period metrics
let CurrentMetrics =
    CurrentDailyActivity
    | summarize
        CurrentDays = count(),
        CurrentDailyAverage = avg(Connections),
        CurrentMin = min(Connections),
        CurrentMax = max(Connections);

// Historical baseline metrics
let BaselineMetrics =
    BaselineDailyActivity
    | summarize
        BaselineDays = count(),
        BaselineDailyAverage = avg(Connections),
        BaselineMin = min(Connections),
        BaselineMax = max(Connections);

CurrentMetrics
| extend JoinKey = 1
| join kind=inner (
    BaselineMetrics
    | extend JoinKey = 1
) on JoinKey
| extend PercentDifference = iff(
    isnull(BaselineDailyAverage) or BaselineDailyAverage == 0,
    real(null),
    round(
        100.0 * (CurrentDailyAverage - BaselineDailyAverage)
        / BaselineDailyAverage,
        1
    )
)
| project
    CurrentDays,
    CurrentDailyAverage = round(CurrentDailyAverage, 0),
    CurrentMin,
    CurrentMax,
    BaselineDays,
    BaselineDailyAverage = round(BaselineDailyAverage, 0),
    BaselineMin,
    BaselineMax,
    PercentDifference

// Traffic distribution in the workbook-selected period
let CurrentTraffic =
    DeviceNetworkEvents
    | where Timestamp {TimeRange}
    | extend NetworkScope = case(
        ActionType == "ListeningConnectionCreated", "Listening",
        RemoteIP in ("127.0.0.1", "::1"), "Loopback",
        RemoteIP startswith "fe80:"
            or RemoteIP startswith "fc"
            or RemoteIP startswith "fd", "Internal",
        ipv4_is_private(RemoteIP), "Internal",
        isnotempty(RemoteIP), "External",
        "Unknown"
    )
    | summarize CurrentConnections = count() by NetworkScope;

// Start of the selected workbook period
let SelectedStart =
    toscalar(
        DeviceNetworkEvents
        | where Timestamp {TimeRange}
        | summarize min(Timestamp)
    );

// Traffic distribution during the 30 days before the selected period
let BaselineTraffic =
    DeviceNetworkEvents
    | where Timestamp >= SelectedStart - 30d
    | where Timestamp < SelectedStart
    | extend NetworkScope = case(
        ActionType == "ListeningConnectionCreated", "Listening",
        RemoteIP in ("127.0.0.1", "::1"), "Loopback",
        RemoteIP startswith "fe80:"
            or RemoteIP startswith "fc"
            or RemoteIP startswith "fd", "Internal",
        ipv4_is_private(RemoteIP), "Internal",
        isnotempty(RemoteIP), "External",
        "Unknown"
    )
    | summarize BaselineConnections = count() by NetworkScope;

// Totals used to calculate distribution percentages
let CurrentTotal =
    toscalar(
        CurrentTraffic
        | summarize sum(CurrentConnections)
    );

let BaselineTotal =
    toscalar(
        BaselineTraffic
        | summarize sum(BaselineConnections)
    );

CurrentTraffic
| join kind=fullouter BaselineTraffic on NetworkScope
| extend
    NetworkScope = coalesce(NetworkScope, NetworkScope1),
    CurrentConnections = coalesce(CurrentConnections, 0),
    BaselineConnections = coalesce(BaselineConnections, 0)
| extend
    CurrentPercent = iff(
        CurrentTotal == 0,
        real(null),
        round(100.0 * CurrentConnections / CurrentTotal, 1)
    ),
    BaselinePercent = iff(
        BaselineTotal == 0,
        real(null),
        round(100.0 * BaselineConnections / BaselineTotal, 1)
    )
| extend PercentagePointChange = round(
    CurrentPercent - BaselinePercent,
    1
)
| project
    NetworkScope,
    CurrentPercent,
    BaselinePercent,
    PercentagePointChange
| order by CurrentPercent desc

let CurrentDays = 7;
let BaselineDays = toint('{BaselineDays}');
let CurrentStart = ago(CurrentDays * 1d);
let BaselineStart = ago((CurrentDays + BaselineDays) * 1d);
let BaselineEnd = CurrentStart;

let BaselinePorts =
    DeviceNetworkEvents
    | where Timestamp between (BaselineStart .. BaselineEnd)
    | where isnotempty(RemotePort)
    | summarize by RemotePort, Protocol;
DeviceNetworkEvents
| where Timestamp >= CurrentStart
| where isnotempty(RemotePort)
| summarize
    Connections=count(),
    Devices=dcount(DeviceId),
    Processes=make_set(InitiatingProcessFileName, 10),
    RemoteIPs=make_set(RemoteIP, 10),
    FirstSeen=min(Timestamp),
    LastSeen=max(Timestamp)
    by RemotePort, Protocol
| join kind=leftanti BaselinePorts on RemotePort, Protocol
| order by Devices desc, Connections desc
